func (readback *observeSDKReadback) Do(request *http.Request) (*http.Response, error) {
	if request.Method != http.MethodGet {
		readback.mutations++
		return nil, errors.New("unexpected OCI mutation")
	}
	var payload any
	var etag string
	path := request.URL.Path
	switch {
	case strings.HasPrefix(path, "/20160918/instances/"):
		id := strings.TrimPrefix(path, "/20160918/instances/")
		readback.getInstanceCalls[id]++
		if id == readback.failInstanceID {
			return nil, readback.failure
		}
		instance, found := readback.instances[id]
		if !found {
			return nil, fmt.Errorf("unknown test instance %s", id)
		}
		etag = instance.ETag
		payload = map[string]any{"id": instance.ID, "compartmentId": instance.CompartmentID,
			"availabilityDomain": instance.AvailabilityDomain, "faultDomain": instance.FaultDomain,
			"shape": instance.Shape, "shapeConfig": map[string]any{"ocpus": instance.Ocpus,
				"memoryInGBs": instance.MemoryInGBs}, "lifecycleState": instance.LifecycleState,
			"imageId": instance.ImageID, "metadata": instance.Metadata, "freeformTags": instance.FreeformTags}
	case strings.HasSuffix(path, "/bootVolumeAttachments"):
		id := request.URL.Query().Get("instanceId")
		if _, found := readback.instances[id]; !found {
			return nil, fmt.Errorf("unknown test boot attachment instance %s", id)
		}
		payload = []map[string]any{{"bootVolumeId": "ocid1.bootvolume." + id,
			"instanceId": id, "compartmentId": readback.config.CompartmentID,
			"availabilityDomain": readback.config.AvailabilityDomain, "lifecycleState": "ATTACHED"}}
	case strings.HasPrefix(path, "/20160918/bootVolumes/"):
		id := strings.TrimPrefix(path, "/20160918/bootVolumes/")
		instanceID := strings.TrimPrefix(id, "ocid1.bootvolume.")
		if _, found := readback.instances[instanceID]; !found {
			return nil, fmt.Errorf("unknown test boot volume %s", id)
		}
		size := int64(readback.config.BootVolumeGB)
		if instanceID == readback.badBootID {
			size++
		}
		payload = map[string]any{"id": id, "compartmentId": readback.config.CompartmentID,
			"imageId": readback.config.ImageID, "sizeInGBs": size,
			"vpusPerGB": readback.config.BootVolumeVPUsPerGB}
	case strings.HasSuffix(path, "/vnicAttachments"):
		id := request.URL.Query().Get("instanceId")
		if _, found := readback.instances[id]; !found {
			return nil, fmt.Errorf("unknown test VNIC attachment instance %s", id)
		}
		payload = []map[string]any{{"vnicId": "ocid1.vnic." + id, "instanceId": id,
			"subnetId": readback.config.SubnetID, "lifecycleState": "ATTACHED"}}
	case strings.HasPrefix(path, "/20160918/vnics/"):
		id := strings.TrimPrefix(path, "/20160918/vnics/")
		instanceID := strings.TrimPrefix(id, "ocid1.vnic.")
		instance, found := readback.instances[instanceID]
		if !found {
			return nil, fmt.Errorf("unknown test VNIC %s", id)
		}
		payload = map[string]any{"id": id, "subnetId": readback.config.SubnetID,
			"privateIp": instance.PrivateIP, "nsgIds": readback.config.NetworkSecurityGroupIDs,
			"skipSourceDestCheck": false, "lifecycleState": "AVAILABLE"}
	default:
		return nil, fmt.Errorf("unexpected OCI test request %s", request.URL)
	}
	wire, err := json.Marshal(payload)
	if err != nil {
		return nil, err
	}
	header := make(http.Header)
	header.Set("Content-Type", "application/json")
	if etag != "" {
		header.Set("etag", etag)
	}
	return &http.Response{StatusCode: http.StatusOK, Header: header,
		Body: io.NopCloser(bytes.NewReader(wire)), Request: request}, nil
}

func (provider *sdkProvider) GetInstance(ctx context.Context, id string) (CloudInstance, error) {
	response, err := provider.compute.GetInstance(ociclient.RequestContext(ctx), core.GetInstanceRequest{InstanceId: new(id)})
	if err != nil {
		return CloudInstance{}, fmt.Errorf("get OCI instance: %w", err)
	}
	instance := cloudInstance(response.Instance, stringValue(response.Etag))
	if instance.LifecycleState != "TERMINATED" && instance.LifecycleState != "TERMINATING" {
		if privateIP, ok := provider.verified.lookup(ctx, instance.ID, instance.ETag); ok &&
			instance.CompartmentID == provider.config.CompartmentID &&
			instance.AvailabilityDomain == provider.config.AvailabilityDomain {
			instance.PrivateIP = privateIP
			return instance, nil
		}
		privateIP, err := provider.verifyInstanceStorageAndNetwork(ctx, instance)
		if err != nil {
			provider.verified.forget(instance.ID)
			return CloudInstance{}, err
		}
		provider.verified.store(instance.ID, instance.ETag, privateIP)
		instance.PrivateIP = privateIP
	}
	return instance, nil
}

func (provider *sdkProvider) verifyInstanceStorageAndNetwork(ctx context.Context, instance CloudInstance) (string, error) {
	return verifyInstanceStorageAndNetwork(ctx, provider.config, instance, provider.compute, provider.storage, provider.network)
}

func verifyInstanceStorageAndNetwork(ctx context.Context, config RegionConfig, instance CloudInstance,
	compute instanceAttachmentReader, storage bootVolumeReader, network vnicReader) (string, error) {
	if instance.CompartmentID != config.CompartmentID ||
		instance.AvailabilityDomain != config.AvailabilityDomain {
		return "", ErrForeignResource
	}
	boots, err := compute.ListBootVolumeAttachments(sdkObservationContext(ctx, compute), core.ListBootVolumeAttachmentsRequest{
		CompartmentId: new(instance.CompartmentID), AvailabilityDomain: new(instance.AvailabilityDomain),
		InstanceId: new(instance.ID),
	})
	if err != nil {
		return "", fmt.Errorf("list exact instance boot attachment: %w", err)
	}
	if len(boots.Items) == 0 && stringValue(boots.OpcNextPage) == "" {
		return "", fmt.Errorf("%w: boot volume attachment is not visible yet", ErrOutcomeUnknown)
	}
	if len(boots.Items) == 1 && stringValue(boots.OpcNextPage) == "" &&
		(boots.Items[0].LifecycleState == core.BootVolumeAttachmentLifecycleStateAttaching ||
			boots.Items[0].LifecycleState == core.BootVolumeAttachmentLifecycleStateDetaching) &&
		stringValue(boots.Items[0].InstanceId) == instance.ID {
		return "", fmt.Errorf("%w: boot volume attachment is transitioning", ErrOutcomeUnknown)
	}
	if len(boots.Items) != 1 || stringValue(boots.OpcNextPage) != "" ||
		boots.Items[0].LifecycleState != core.BootVolumeAttachmentLifecycleStateAttached ||
		stringValue(boots.Items[0].InstanceId) != instance.ID ||
		stringValue(boots.Items[0].BootVolumeId) == "" {
		return "", fmt.Errorf("%w: instance has no single attached boot volume", ErrForeignResource)
	}
	boot, err := storage.GetBootVolume(sdkObservationContext(ctx, storage), core.GetBootVolumeRequest{
		BootVolumeId: boots.Items[0].BootVolumeId,
	})
	if err != nil {
		return "", fmt.Errorf("get exact instance boot volume: %w", err)
	}
	if stringValue(boot.Id) != stringValue(boots.Items[0].BootVolumeId) ||
		stringValue(boot.CompartmentId) != config.CompartmentID ||
		instance.ImageID == "" || stringValue(boot.ImageId) != instance.ImageID ||
		int64Value(boot.SizeInGBs) != int64(config.BootVolumeGB) ||
		int64Value(boot.VpusPerGB) != int64(config.BootVolumeVPUsPerGB) {
		return "", errors.Join(ErrForeignResource,
			fmt.Errorf("%w: instance boot image, size, or tier differs from the instance image and fleet pins", ErrImageNotQualified))
	}
	attachments, err := compute.ListVnicAttachments(sdkObservationContext(ctx, compute), core.ListVnicAttachmentsRequest{
		CompartmentId: new(instance.CompartmentID), InstanceId: new(instance.ID),
	})
	if err != nil {
		return "", fmt.Errorf("list exact instance VNIC: %w", err)
	}
	if len(attachments.Items) == 0 && stringValue(attachments.OpcNextPage) == "" {
		return "", fmt.Errorf("%w: primary VNIC attachment is not visible yet", ErrOutcomeUnknown)
	}
	if len(attachments.Items) == 1 && stringValue(attachments.OpcNextPage) == "" &&
		(attachments.Items[0].LifecycleState == core.VnicAttachmentLifecycleStateAttaching ||
			attachments.Items[0].LifecycleState == core.VnicAttachmentLifecycleStateDetaching) &&
		stringValue(attachments.Items[0].InstanceId) == instance.ID {
		return "", fmt.Errorf("%w: primary VNIC attachment is transitioning", ErrOutcomeUnknown)
	}
	if len(attachments.Items) != 1 || stringValue(attachments.OpcNextPage) != "" ||
		attachments.Items[0].LifecycleState != core.VnicAttachmentLifecycleStateAttached ||
		stringValue(attachments.Items[0].InstanceId) != instance.ID ||
		stringValue(attachments.Items[0].VnicId) == "" {
		return "", fmt.Errorf("%w: instance has no single attached primary VNIC", ErrForeignResource)
	}
	vnic, err := network.GetVnic(sdkObservationContext(ctx, network), core.GetVnicRequest{VnicId: attachments.Items[0].VnicId})
	if err != nil {
		return "", fmt.Errorf("get exact instance VNIC: %w", err)
	}
	gotNSGs := slices.Clone(vnic.NsgIds)
	wantNSGs := slices.Clone(config.NetworkSecurityGroupIDs)
	slices.Sort(gotNSGs)
	slices.Sort(wantNSGs)
	if stringValue(vnic.Id) != stringValue(attachments.Items[0].VnicId) ||
		stringValue(vnic.SubnetId) != config.SubnetID ||
		!validManagedPrivateIP(stringValue(vnic.PrivateIp)) || stringValue(vnic.PublicIp) != "" ||
		vnic.SkipSourceDestCheck != nil && *vnic.SkipSourceDestCheck ||
		vnic.LifecycleState != core.VnicLifecycleStateAvailable ||
		!slices.Equal(gotNSGs, wantNSGs) {
		return "", fmt.Errorf("%w: instance VNIC differs from the private subnet and NSG pins", ErrForeignResource)
	}
	return stringValue(vnic.PrivateIp), nil
}

func testJournalBucket(t *testing.T) jetstream.KeyValue {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 20*time.Second)
	defer cancel()
	runtime, err := startAuthenticatedJournal(ctx, authenticatedJournalConfig(t, "oci-journal-test"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = runtime.Close() })
	journal, err := OpenJournal(ctx, runtime.JetStream(), 1)
	if err != nil {
		t.Fatal(err)
	}
	return journal.kv
}

func authenticatedJournalConfig(t *testing.T, instance string) natscell.Config {
	t.Helper()
	const cell = "lab"
	root := t.TempDir()
	write := func(name string, wire []byte) string {
		t.Helper()
		path := filepath.Join(root, name)
		if err := os.WriteFile(path, wire, 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	key := func(kind nkeys.PrefixByte) (nkeys.KeyPair, string) {
		t.Helper()
		pair, err := nkeys.CreatePair(kind)
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(pair.Wipe)
		public, err := pair.PublicKey()
		if err != nil {
			t.Fatal(err)
		}
		return pair, public
	}
	operator, operatorID := key(nkeys.PrefixByteOperator)
	system, systemID := key(nkeys.PrefixByteAccount)
	account, accountID := key(nkeys.PrefixByteAccount)
	claimFile := func(name string, claim jwt.Claims, signer nkeys.KeyPair) string {
		t.Helper()
		wire, err := claim.Encode(signer)
		if err != nil {
			t.Fatal(err)
		}
		return write(name, []byte(wire))
	}
	credentials := func(name string, user, signer nkeys.KeyPair, claim *jwt.UserClaims) string {
		t.Helper()
		wire, err := claim.Encode(signer)
		if err != nil {
			t.Fatal(err)
		}
		seed, err := user.Seed()
		if err != nil {
			t.Fatal(err)
		}
		defer clear(seed)
		creds, err := jwt.FormatUserConfig(wire, seed)
		if err != nil {
			t.Fatal(err)
		}
		defer clear(creds)
		return write(name, creds)
	}
	operatorClaim := jwt.NewOperatorClaims(operatorID)
	operatorClaim.SystemAccount = systemID
	accountClaim := jwt.NewAccountClaims(accountID)
	accountClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 64 << 20, DiskStorage: 256 << 20, Streams: 10, Consumer: 10}
	systemUser, systemUserID := key(nkeys.PrefixByteUser)
	systemClaim := jwt.NewUserClaims(systemUserID)
	systemClaim.IssuerAccount = systemID
	systemClaim.Pub.Allow = jwt.StringList{"$SYS.REQ.ACCOUNT." + accountID + ".CLAIMS.UPDATE"}
	systemClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, systemUserID) + ".>"}
	controller, controllerID := key(nkeys.PrefixByteUser)
	controllerClaim := jwt.NewUserClaims(controllerID)
	controllerClaim.IssuerAccount = accountID
	controllerClaim.Pub.Allow = natscell.ControllerPublishes(cell)
	controllerClaim.Pub.Allow.Add("$JS.ACK.>")
	controllerClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, controllerID) + ".>"}
	controllerClaim.Sub.Allow.Add(natscell.ControllerSubscriptions(cell)...)
	controllerClaim.Sub.Allow.Add(protocol.Broker(cell, "ticket", ">"), protocol.Broker(cell, "fence", instance))
	controllerClaim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}

	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now()
	ca := &x509.Certificate{SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: "OCI journal test CA"},
		NotBefore: now.Add(-time.Hour), NotAfter: now.Add(time.Hour), IsCA: true, BasicConstraintsValid: true,
		KeyUsage: x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature}
	caDER, err := x509.CreateCertificate(rand.Reader, ca, ca, &caKey.PublicKey, caKey)
	if err != nil {
		t.Fatal(err)
	}
	peerKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	peer := &x509.Certificate{SerialNumber: big.NewInt(2), Subject: pkix.Name{CommonName: "OCI journal test peer"},
		NotBefore: now.Add(-time.Hour), NotAfter: now.Add(time.Hour), IPAddresses: []net.IP{net.ParseIP("127.0.0.1")},
		KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}}
	peerDER, err := x509.CreateCertificate(rand.Reader, peer, ca, &peerKey.PublicKey, caKey)
	if err != nil {
		t.Fatal(err)
	}
	keyDER, err := x509.MarshalECPrivateKey(peerKey)
	if err != nil {
		t.Fatal(err)
	}
	tlsFiles := natscell.TLSFiles{
		CAFile:   write("ca.pem", pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: caDER})),
		CertFile: write("peer.pem", pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: peerDER})),
		KeyFile:  write("peer-key.pem", pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER})),
	}
	ticketPublic, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	port := listener.Addr().(*net.TCPAddr).Port
	if err := listener.Close(); err != nil {
		t.Fatal(err)
	}
	cfg := natscell.Config{Cell: cell, Instance: instance, Replicas: 1, TLS: tlsFiles,
		CredentialsFile: credentials("controller.creds", controller, account, controllerClaim),
		Embedded: &natscell.Embedded{Host: "127.0.0.1", Port: port, StoreDir: filepath.Join(root, "jetstream"),
			TLS: tlsFiles, RouteTLS: tlsFiles, OperatorJWTFile: claimFile("operator.jwt", operatorClaim, operator),
			SystemJWTFile:         claimFile("system.jwt", jwt.NewAccountClaims(systemID), operator),
			CellJWTFile:           claimFile("cell.jwt", accountClaim, operator),
			SystemCredentialsFile: credentials("system.creds", systemUser, system, systemClaim),
			TicketPublicKeyFile:   write("ticket.pub", []byte(base64.StdEncoding.EncodeToString(ticketPublic))), BrokerIDs: []string{instance}}}
	if err := natscell.ValidateProductionCredentials(cfg); err != nil {
		t.Fatal(err)
	}
	return cfg
}

func startAuthenticatedJournal(ctx context.Context, cfg natscell.Config) (_ *authenticatedJournalRuntime, err error) {
	broker, err := natscell.Start(ctx, cfg)
	if err != nil {
		return nil, err
	}
	defer func() {
		if err != nil {
			_ = broker.Close()
		}
	}()
	claim := broker.InitialCellJWT()
	if err = broker.ApplyCellClaim(ctx, 1, claim); err != nil {
		return nil, err
	}
	if err = broker.Bridge().OpenUntil(1, claim, time.Now().Add(5*time.Minute)); err != nil {
		return nil, err
	}
	cfg.URL, cfg.Embedded = broker.URL(), nil
	client, err := natscell.Start(ctx, cfg)
	if err != nil {
		return nil, err
	}
	return &authenticatedJournalRuntime{Runtime: client, broker: broker}, nil
}

func OpenJournal(ctx context.Context, js jetstream.JetStream, replicas int) (*KVJournal, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI journal requires JetStream and one to five replicas")
	}
	kv, err := js.CreateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       journalBucket,
		Description:  "Durable OCI mutation intent and resource ownership",
		MaxValueSize: journalMaxValueSize,
		History:      5,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
		Compression:  true,
	})
	if err != nil {
		if !errors.Is(err, jetstream.ErrBucketExists) {
			return nil, fmt.Errorf("create OCI journal bucket: %w", err)
		}
		kv, err = js.KeyValue(ctx, journalBucket)
		if err != nil {
			return nil, fmt.Errorf("open existing OCI journal bucket: %w", err)
		}
		status, statusErr := kv.Status(ctx)
		if statusErr != nil {
			return nil, fmt.Errorf("inspect OCI journal bucket: %w", statusErr)
		}
		config := status.Config()
		if config.Replicas != replicas || config.Storage != jetstream.FileStorage || config.TTL != 0 || config.History < 2 || config.MaxValueSize > journalMaxValueSize {
			return nil, errors.New("existing OCI journal bucket has incompatible durability limits")
		}
	}
	return NewKVJournal(kv)
}

func NewKVJournal(kv jetstream.KeyValue) (*KVJournal, error) {
	if kv == nil {
		return nil, errors.New("OCI journal KV bucket is required")
	}
	return &KVJournal{kv: kv}, nil
}

func (journal *KVJournal) RecordIntent(ctx context.Context, intent OperationIntent) error {
	if err := validateIntent(intent); err != nil {
		return err
	}
	entry := journalEntry{SchemaVersion: journalSchema, Kind: "operation", Intent: intent}
	data, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("encode OCI operation intent: %w", err)
	}
	key := operationKey(intent)
	_, err = journal.kv.Create(ctx, key, data)
	if err == nil {
		return nil
	}
	if !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("persist OCI operation intent: %w", err)
	}
	current, err := journal.read(ctx, key)
	if err != nil {
		return err
	}
	if current.Kind != "operation" || !sameIntent(current.Intent, intent) {
		return errors.New("OCI operation key was reused for a different mutation")
	}
	return nil
}

func (journal *KVJournal) RecordResult(ctx context.Context, result OperationResult) error {
	if err := validateIntent(result.Intent); err != nil {
		return err
	}
	if result.Intent.Action == actionVolumeAttach && !result.Unknown && (result.ResourceID == "" || result.ETag == "") {
		return errors.New("confirmed OCI volume attachment result requires an attachment ID and ETag")
	}
	if result.Intent.Action == actionVolumeResize && !result.Unknown && result.ResourceID != result.Intent.VolumeID {
		return errors.New("confirmed OCI volume resize result must name its exact volume")
	}
	key := operationKey(result.Intent)
	if result.RecordedAt.IsZero() {
		result.RecordedAt = time.Now().UTC()
	}
	for range 4 {
		entry, err := journal.kv.Get(ctx, key)
		if err != nil {
			return fmt.Errorf("read OCI operation intent: %w", err)
		}
		current, err := decodeJournalEntry(entry.Value())
		if err != nil {
			return err
		}
		if current.Kind != "operation" || !sameIntent(current.Intent, result.Intent) {
			return errors.New("OCI operation result has no matching durable intent")
		}
		// The operation's first committed intent owns the retry window. A
		// retried caller's freshly generated CreatedAt must never refresh it.
		result.Intent = current.Intent
		if !current.Result.RecordedAt.IsZero() && !current.Result.Unknown {
			if result.Unknown {
				// A late timeout must not overwrite a confirmed provider result.
				return journal.repairOwnership(ctx, current.Result)
			}
			if !sameResult(current.Result, result) {
				return errors.New("OCI operation already has a different confirmed result")
			}
			return journal.repairOwnership(ctx, current.Result)
		}
		current.Result = result
		data, err := json.Marshal(current)
		if err != nil {
			return fmt.Errorf("encode OCI operation result: %w", err)
		}
		if _, err := journal.kv.Update(ctx, key, data, entry.Revision()); err != nil {
			if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
				continue
			}
			// The write outcome can be unknown. Re-read on the next call rather
			// than changing the accepted identity using a fresh revision here.
			return fmt.Errorf("record OCI operation result: %w", err)
		}
		return journal.repairOwnership(ctx, result)
	}
	return errors.New("OCI operation result CAS did not converge")
}

func (journal *KVJournal) GetResult(ctx context.Context, intent OperationIntent) (OperationResult, bool, error) {
	if err := validateIntent(intent); err != nil {
		return OperationResult{}, false, err
	}
	entry, err := journal.read(ctx, operationKey(intent))
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return OperationResult{}, false, nil
	}
	if err != nil {
		return OperationResult{}, false, err
	}
	if entry.Kind != "operation" || !sameIntent(entry.Intent, intent) {
		return OperationResult{}, false, errors.New("OCI result lookup has no matching durable intent")
	}
	result := entry.Result
	if result.RecordedAt.IsZero() {
		result.Intent = entry.Intent
		return result, false, nil
	}
	result.Intent = entry.Intent
	return result, true, nil
}

func (journal *KVJournal) GetOperation(ctx context.Context, scope OperationScope) (OperationIntent, bool, error) {
	if scope.Action == "" || scope.Key == "" || scope.Generation == 0 || scope.Owner == "" {
		return OperationIntent{}, false, errors.New("OCI operation lookup scope is incomplete")
	}
	if _, err := scope.Region.OCIRegion(); err != nil {
		return OperationIntent{}, false, err
	}
	keyIntent := OperationIntent{
		Action: scope.Action, Key: scope.Key, Region: scope.Region,
		Generation: scope.Generation, Owner: scope.Owner,
	}
	entry, err := journal.read(ctx, operationKey(keyIntent))
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return OperationIntent{}, false, nil
	}
	if err != nil {
		return OperationIntent{}, false, err
	}
	intent := entry.Intent
	if entry.Kind != "operation" || intent.Action != scope.Action || intent.Key != scope.Key ||
		intent.Region != scope.Region || intent.Generation != scope.Generation || intent.Owner != scope.Owner {
		return OperationIntent{}, false, errors.New("OCI operation lookup has no matching durable intent")
	}
	return intent, true, nil
}

func (journal *KVJournal) RecordBootBinding(ctx context.Context, binding BootBinding) error {
	if !validBootBinding(binding) {
		return errors.New("OCI boot binding is incomplete")
	}
	entry := journalEntry{SchemaVersion: journalSchema, Kind: "boot-binding", BootBinding: binding}
	data, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("encode OCI boot binding: %w", err)
	}
	key := ownershipKey("boot-binding", binding.InstanceID)
	if _, err := journal.kv.Create(ctx, key, data); err == nil {
		return nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("persist OCI boot binding: %w", err)
	}
	current, err := journal.read(ctx, key)
	if err != nil {
		return err
	}
	if current.Kind != "boot-binding" || current.BootBinding != binding {
		return errors.New("OCI instance is already bound to a different boot volume")
	}
	return nil
}

func (journal *KVJournal) recordOwnership(ctx context.Context, resourceKind string, identity ResourceIdentity) error {
	entry := journalEntry{SchemaVersion: journalSchema, Kind: resourceKind, Identity: identity}
	data, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("encode OCI %s ownership: %w", resourceKind, err)
	}
	key := ownershipKey(resourceKind, identity.ID)
	_, err = journal.kv.Create(ctx, key, data)
	if err == nil {
		return nil
	}
	if !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("persist OCI %s ownership: %w", resourceKind, err)
	}
	existing, err := journal.read(ctx, key)
	if err != nil {
		return err
	}
	if existing.Kind != resourceKind || existing.Identity != identity {
		return fmt.Errorf("OCI %s is already owned by another controller identity", resourceKind)
	}
	return nil
}

func (journal *KVJournal) isOwned(ctx context.Context, kind string, identity ResourceIdentity) (bool, error) {
	if identity.ID == "" || identity.Generation == 0 || identity.Owner == "" || identity.CreateKey == "" {
		return false, nil
	}
	entry, err := journal.read(ctx, ownershipKey(kind, identity.ID))
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return journal.repairOwnershipFromOperation(ctx, kind, identity)
	}
	if err != nil {
		return false, err
	}
	if entry.SchemaVersion != journalSchema || entry.Kind != kind {
		return false, nil
	}
	if entry.Identity == identity {
		return true, nil
	}

func (journal *KVJournal) read(ctx context.Context, key string) (journalEntry, error) {
	entry, err := journal.kv.Get(ctx, key)
	if err != nil {
		return journalEntry{}, err
	}
	return decodeJournalEntry(entry.Value())
}

func decodeJournalEntry(data []byte) (journalEntry, error) {
	var record journalEntry
	if err := json.Unmarshal(data, &record, json.RejectUnknownMembers(true)); err != nil {
		return journalEntry{}, fmt.Errorf("decode OCI journal record: %w", err)
	}
	if record.SchemaVersion != journalSchema {
		return journalEntry{}, errors.New("OCI journal record has unsupported schema version")
	}
	return record, nil
}

func (journal *KVJournal) repairOwnership(ctx context.Context, result OperationResult) error {
	if result.Unknown || result.ResourceID == "" {
		return nil
	}
	identity := ResourceIdentity{
		ID: result.ResourceID, Region: result.Intent.Region, Generation: result.Intent.Generation,
		Owner: result.Intent.Owner, CreateKey: result.Intent.CreateKey,
	}
	switch result.Intent.Action {
	case actionLaunch:
		return journal.recordOwnership(ctx, "instance", identity)
	case actionVolumeCreate:
		identity.AvailabilityDomain = result.Intent.AvailabilityDomain
		identity.SizeGB = result.Intent.SizeGB
		return journal.recordOwnership(ctx, "volume", identity)
	case actionVolumeAttach:
		return journal.recordAttachmentOwnership(ctx, attachmentIdentityFromResult(result), result)
	case actionVolumeResize:
		return journal.advanceVolumeOwnership(ctx, result)
	default:
		return nil
	}
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func clientOptions(cfg Config) ([]nats.Option, error) {
	connectTimeout := 12 * time.Second
	if cfg.ClientRole == "host" {
		connectTimeout = 3 * time.Second
	}
	options := []nats.Option{nats.Name("terrascale-" + cfg.Cell + "-" + cfg.Instance), nats.Timeout(connectTimeout),
		nats.ErrorHandler(ErrorHandler)}
	// Renewal applies to every authentication mode: an NKey-seed client has
	// no JWT to reload but must still present a renewed certificate.
	var materials *clientMaterialSource
	if cfg.ReloadClientMaterial != nil {
		materials = newClientMaterialSource(cfg, "")
	}
	if cfg.CredentialsFile != "" {
		data, err := readPrivateFile(cfg.CredentialsFile, 64<<10)
		if err != nil {
			return nil, fmt.Errorf("regional JWT credentials: %w", err)
		}
		pair, err := nkeys.ParseDecoratedUserNKey(data)
		clear(data)
		if err != nil {
			return nil, fmt.Errorf("regional JWT credentials: %w", err)
		}
		public, err := pair.PublicKey()
		pair.Wipe()
		if err != nil {
			return nil, err
		}
		options = append(options, nats.CustomInboxPrefix(inboxPrefix(cfg.Cell, public)))
		source := materials
		if source == nil {
			source = newClientMaterialSource(cfg, public)
		}
		source.user = public
		// The JWT and its signature come from one resolved file per handshake.
		var handshake ClientMaterial
		options = append(options, nats.UserJWT(func() (string, error) {
			handshake = source.current()
			data, err := readPrivateFile(handshake.CredentialsFile, 64<<10)
			if err != nil {
				return "", err
			}
			defer clear(data)
			return nkeys.ParseDecoratedJWT(data)
		}, func(nonce []byte) ([]byte, error) {
			path := handshake.CredentialsFile
			if path == "" {
				path = cfg.CredentialsFile
			}
			return signNKeyFile(path, nonce)
		}))
	}
	if cfg.NKeySeedFile != "" {
		data, err := readPrivateFile(cfg.NKeySeedFile, 4096)
		if err != nil {
			return nil, fmt.Errorf("regional NKey seed: %w", err)
		}
		pair, err := nkeys.ParseDecoratedUserNKey(data)
		clear(data)
		if err != nil {
			return nil, fmt.Errorf("regional NKey seed: %w", err)
		}
		public, err := pair.PublicKey()
		pair.Wipe()
		if err != nil {
			return nil, err
		}
		options = append(options, nats.CustomInboxPrefix(inboxPrefix(cfg.Cell, public)))
		options = append(options, nats.Nkey(public, func(nonce []byte) ([]byte, error) {
			return signNKeyFile(cfg.NKeySeedFile, nonce)
		}))
	}
	if cfg.TLS.complete() && cfg.Embedded == nil {
		tlsConfig, err := loadTLS(cfg.TLS, false)
		if err != nil {
			return nil, err
		}
		dialer := &tlsFirstDialer{config: tlsConfig, timeout: connectTimeout}
		if materials != nil {
			dialer.reload = materials.tlsConfig
		}
		if len(cfg.OperatorForward) != 0 {
			_, destinations, err := operatorForwarding(cfg)
			if err != nil {
				return nil, err
			}
			dialer.forward = destinations
			options = append(options, nats.IgnoreDiscoveredServers())
		}
		options = append(options, nats.SetCustomDialer(dialer))
	}
	return options, nil
}

func (d *tlsFirstDialer) Dial(network, address string) (net.Conn, error) {
	destination, config := address, d.config
	if d.reload != nil {
		if current, err := d.reload(); err == nil {
			config = current
		}
	}
	if len(d.forward) != 0 {
		if network != "tcp" {
			return nil, errors.New("operator forward requires TCP")
		}
		mapped, ok := d.forward[address]
		if !ok {
			return nil, fmt.Errorf("NATS controller %q has no operator forward", address)
		}
		host, _, err := net.SplitHostPort(address)
		if err != nil {
			return nil, err
		}
		destination = mapped
		config = config.Clone()
		config.ServerName = host
	}
	conn, err := tls.DialWithDialer(&net.Dialer{Timeout: d.timeout}, network, destination, config)
	if err != nil {
		return nil, err
	}
	return conn, nil
}

func startBridge(s *server.Server, address string, tlsConfig *tls.Config, account string) (*Bridge, error) {
	if s == nil || tlsConfig == nil || account == "" {
		return nil, errors.New("production broker bridge is incomplete")
	}
	listener, err := tls.Listen("tcp", address, tlsConfig)
	if err != nil {
		return nil, fmt.Errorf("listen for regional broker clients: %w", err)
	}
	b := &Bridge{server: s, listener: listener, account: account, pairs: make(map[*bridgePair]struct{}), listeners: make(map[net.Listener]struct{})}
	go b.accept(listener)
	return b, nil
}

func (b *Bridge) OpenUntil(sequence uint64, rawJWT string, deadline time.Time) error {
	if b == nil || sequence == 0 || rawJWT == "" || !time.Now().Before(deadline) {
		return errors.New("broker bridge ticket is invalid or expired")
	}
	if _, err := b.server.LookupAccount(b.account); err != nil {
		return fmt.Errorf("load broker account: %w", err)
	}
	accountz, err := b.server.Accountz(&server.AccountzOptions{Account: b.account})
	if err != nil || accountz.Account == nil || accountz.Account.Jwt != rawJWT {
		return errors.New("broker account JWT was not applied locally")
	}
	b.mu.Lock()
	if b.closed || sequence < b.floor {
		b.mu.Unlock()
		return errors.New("broker bridge is closed or claim sequence is stale")
	}
	var pairs map[*bridgePair]struct{}
	if b.open && (b.sequence != sequence || b.jwt != rawJWT) {
		pairs = b.fenceLocked()
	}
	b.sequence, b.jwt, b.deadline, b.open = sequence, rawJWT, deadline, true
	if b.timer != nil {
		b.timer.Stop()
	}
	b.timer = time.AfterFunc(time.Until(deadline), func() {
		b.mu.Lock()
		var expired map[*bridgePair]struct{}
		if b.open && b.sequence == sequence && b.deadline.Equal(deadline) {
			expired = b.fenceLocked()
		}
		b.mu.Unlock()
		closeBridgeExternal(expired)
	})
	b.mu.Unlock()
	closeBridgeExternal(pairs)
	return nil
}

func (b *Bridge) accept(listener net.Listener) {
	defer func() {
		b.mu.Lock()
		delete(b.listeners, listener)
		b.mu.Unlock()
	}()
	for {
		external, err := listener.Accept()
		if err != nil {
			return
		}
		b.mu.Lock()
		allowed := b.open && time.Now().Before(b.deadline) && !b.closed
		b.mu.Unlock()
		if !allowed {
			_ = external.Close()
			continue
		}
		go b.serve(external, listener)
	}
}

func (b *Bridge) serve(external net.Conn, listener net.Listener) {
	defer external.Close()
	if err := external.SetDeadline(time.Now().Add(5 * time.Second)); err != nil {
		return
	}
	if err := external.(*tls.Conn).Handshake(); err != nil {
		return
	}
	if err := external.SetDeadline(time.Time{}); err != nil {
		return
	}
	internal, err := b.server.InProcessConnForAccount(b.account)
	if err != nil {
		return
	}
	pair := &bridgePair{external: external, internal: internal, listener: listener}
	b.mu.Lock()
	_, additional := b.listeners[listener]
	if b.closed || listener != b.listener && !additional || !b.open || !time.Now().Before(b.deadline) {
		b.mu.Unlock()
		pair.close()
		return
	}
	b.pairs[pair] = struct{}{}
	b.mu.Unlock()
	done := make(chan struct{}, 2)
	go func() { _, _ = io.Copy(internal, external); done <- struct{}{} }()
	go func() { _, _ = io.Copy(external, internal); done <- struct{}{} }()
	<-done
	pair.close()
	<-done
	b.mu.Lock()
	delete(b.pairs, pair)
	b.mu.Unlock()
}
